frappe.ui.form.on('Journal Entry', {
    refresh: function(frm) {
        try {
            updateCustomMonth(frm);
        } catch (e) {
            console.log('Błąd w refresh, ale kontynuuję:', e);
        }
    },

    posting_date: function(frm) {
        try {
            updateCustomMonth(frm);
        } catch (e) {
            console.log('Błąd w posting_date, ale kontynuuję:', e);
        }
    }
});

function updateCustomMonth(frm) {
    if (frm && frm.doc && frm.doc.posting_date) {
        try {
            let posting_date = new Date(frm.doc.posting_date);

            // Sprawdź czy data jest poprawna
            if (isNaN(posting_date.getTime())) {
                console.log('Nieprawidłowa data:', frm.doc.posting_date);
                return;
            }

            let month = posting_date.getMonth() + 1;
            let monthFormatted = month.toString().padStart(2, '0');

            frm.set_value('custom_month', monthFormatted);
            console.log('OK - ustawiono:', monthFormatted);
        } catch (e) {
            console.log('Błąd w updateCustomMonth:', e);
        }
    } else {
        // Brak daty - wyczyść pole
        if (frm && frm.set_value) {
            frm.set_value('custom_month', '');
        }
    }
}

