frappe.ui.form.on('Sales Invoice', {
    refresh: function(frm) {
        if (frm.doc.docstatus === 1 && frm.doc.ksef_status === 'Oczekuje') {  // tylko po submit, jeśli nie wysłano
            frm.add_custom_button(__('Wyślij do KSeF'), function() {
                frappe.call({
                    method: 'erpnext_poland.ksef_utils.send_to_ksef',  // Twój Python method
                    args: { invoice_name: frm.doc.name },
                    callback: function(r) {
                        if (!r.exc) {
                            frm.reload_doc();  // odśwież, by pokazać nowy status
                        }
                    }
                });
            });
        }
    }
});
